function createBaseFrameData(): FrameData {
  return { lapNumber: 0, racePhase: 0, numCoins: 0, primaryItem: 0, secondaryItem: 0, placement: 0, raceCourse: 0 };
}

export const FrameData: MessageFns<FrameData> = {
  encode(message: FrameData, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.lapNumber !== 0) {
      writer.uint32(8).int32(message.lapNumber);
    }
    if (message.racePhase !== 0) {
      writer.uint32(16).int32(message.racePhase);
    }
    if (message.numCoins !== 0) {
      writer.uint32(24).int32(message.numCoins);
    }
    if (message.primaryItem !== 0) {
      writer.uint32(32).int32(message.primaryItem);
    }
    if (message.secondaryItem !== 0) {
      writer.uint32(40).int32(message.secondaryItem);
    }
    if (message.placement !== 0) {
      writer.uint32(48).int32(message.placement);
    }
    if (message.raceCourse !== 0) {
      writer.uint32(56).int32(message.raceCourse);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): FrameData {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseFrameData();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 8) {
            break;
          }

          message.lapNumber = reader.int32() as any;
          continue;
        }
        case 2: {
          if (tag !== 16) {
            break;
          }

          message.racePhase = reader.int32() as any;
          continue;
        }
        case 3: {
          if (tag !== 24) {
            break;
          }

          message.numCoins = reader.int32() as any;
          continue;
        }
        case 4: {
          if (tag !== 32) {
            break;
          }

          message.primaryItem = reader.int32() as any;
          continue;
        }
        case 5: {
          if (tag !== 40) {
            break;
          }

          message.secondaryItem = reader.int32() as any;
          continue;
        }
        case 6: {
          if (tag !== 48) {
            break;
          }

          message.placement = reader.int32() as any;
          continue;
        }
        case 7: {
          if (tag !== 56) {
            break;
          }

          message.raceCourse = reader.int32() as any;
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): FrameData {
    return {
      lapNumber: isSet(object.lapNumber)
        ? lapNumberFromJSON(object.lapNumber)
        : isSet(object.lap_number)
        ? lapNumberFromJSON(object.lap_number)
        : 0,
      racePhase: isSet(object.racePhase)
        ? racePhaseFromJSON(object.racePhase)
        : isSet(object.race_phase)
        ? racePhaseFromJSON(object.race_phase)
        : 0,
      numCoins: isSet(object.numCoins)
        ? numCoinsFromJSON(object.numCoins)
        : isSet(object.num_coins)
        ? numCoinsFromJSON(object.num_coins)
        : 0,
      primaryItem: isSet(object.primaryItem)
        ? itemFromJSON(object.primaryItem)
        : isSet(object.primary_item)
        ? itemFromJSON(object.primary_item)
        : 0,
      secondaryItem: isSet(object.secondaryItem)
        ? itemFromJSON(object.secondaryItem)
        : isSet(object.secondary_item)
        ? itemFromJSON(object.secondary_item)
        : 0,
      placement: isSet(object.placement) ? placementFromJSON(object.placement) : 0,
      raceCourse: isSet(object.raceCourse)
        ? raceCourseFromJSON(object.raceCourse)
        : isSet(object.race_course)
        ? raceCourseFromJSON(object.race_course)
        : 0,
    };
  },

  toJSON(message: FrameData): unknown {
    const obj: any = {};
    if (message.lapNumber !== 0) {
      obj.lapNumber = lapNumberToJSON(message.lapNumber);
    }
    if (message.racePhase !== 0) {
      obj.racePhase = racePhaseToJSON(message.racePhase);
    }
    if (message.numCoins !== 0) {
      obj.numCoins = numCoinsToJSON(message.numCoins);
    }
    if (message.primaryItem !== 0) {
      obj.primaryItem = itemToJSON(message.primaryItem);
    }
    if (message.secondaryItem !== 0) {
      obj.secondaryItem = itemToJSON(message.secondaryItem);
    }
    if (message.placement !== 0) {
      obj.placement = placementToJSON(message.placement);
    }
    if (message.raceCourse !== 0) {
      obj.raceCourse = raceCourseToJSON(message.raceCourse);
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<FrameData>, I>>(base?: I): FrameData {
    return FrameData.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<FrameData>, I>>(object: I): FrameData {
    const message = createBaseFrameData();
    message.lapNumber = object.lapNumber ?? 0;
    message.racePhase = object.racePhase ?? 0;
    message.numCoins = object.numCoins ?? 0;
    message.primaryItem = object.primaryItem ?? 0;
    message.secondaryItem = object.secondaryItem ?? 0;
    message.placement = object.placement ?? 0;
    message.raceCourse = object.raceCourse ?? 0;
    return message;
  },
};

function createBaseRaceCourseInfo(): RaceCourseInfo {
  return { name: "", shortenedName: 0, type: 0, numberOfLaps: 0 };
}

export const RaceCourseInfo: MessageFns<RaceCourseInfo> = {
  encode(message: RaceCourseInfo, writer: BinaryWriter = new BinaryWriter()): BinaryWriter {
    if (message.name !== "") {
      writer.uint32(10).string(message.name);
    }
    if (message.shortenedName !== 0) {
      writer.uint32(16).int32(message.shortenedName);
    }
    if (message.type !== 0) {
      writer.uint32(24).int32(message.type);
    }
    if (message.numberOfLaps !== 0) {
      writer.uint32(32).int32(message.numberOfLaps);
    }
    return writer;
  },

  decode(input: BinaryReader | Uint8Array, length?: number): RaceCourseInfo {
    const reader = input instanceof BinaryReader ? input : new BinaryReader(input);
    const end = length === undefined ? reader.len : reader.pos + length;
    const message = createBaseRaceCourseInfo();
    while (reader.pos < end) {
      const tag = reader.uint32();
      switch (tag >>> 3) {
        case 1: {
          if (tag !== 10) {
            break;
          }

          message.name = reader.string();
          continue;
        }
        case 2: {
          if (tag !== 16) {
            break;
          }

          message.shortenedName = reader.int32() as any;
          continue;
        }
        case 3: {
          if (tag !== 24) {
            break;
          }

          message.type = reader.int32() as any;
          continue;
        }
        case 4: {
          if (tag !== 32) {
            break;
          }

          message.numberOfLaps = reader.int32() as any;
          continue;
        }
      }
      if ((tag & 7) === 4 || tag === 0) {
        break;
      }
      reader.skip(tag & 7);
    }
    return message;
  },

  fromJSON(object: any): RaceCourseInfo {
    return {
      name: isSet(object.name) ? globalThis.String(object.name) : "",
      shortenedName: isSet(object.shortenedName)
        ? raceCourseFromJSON(object.shortenedName)
        : isSet(object.shortened_name)
        ? raceCourseFromJSON(object.shortened_name)
        : 0,
      type: isSet(object.type) ? raceCourseInfo_RaceCourseTypeFromJSON(object.type) : 0,
      numberOfLaps: isSet(object.numberOfLaps)
        ? lapNumberFromJSON(object.numberOfLaps)
        : isSet(object.number_of_laps)
        ? lapNumberFromJSON(object.number_of_laps)
        : 0,
    };
  },

  toJSON(message: RaceCourseInfo): unknown {
    const obj: any = {};
    if (message.name !== "") {
      obj.name = message.name;
    }
    if (message.shortenedName !== 0) {
      obj.shortenedName = raceCourseToJSON(message.shortenedName);
    }
    if (message.type !== 0) {
      obj.type = raceCourseInfo_RaceCourseTypeToJSON(message.type);
    }
    if (message.numberOfLaps !== 0) {
      obj.numberOfLaps = lapNumberToJSON(message.numberOfLaps);
    }
    return obj;
  },

  create<I extends Exact<DeepPartial<RaceCourseInfo>, I>>(base?: I): RaceCourseInfo {
    return RaceCourseInfo.fromPartial(base ?? ({} as any));
  },
  fromPartial<I extends Exact<DeepPartial<RaceCourseInfo>, I>>(object: I): RaceCourseInfo {
    const message = createBaseRaceCourseInfo();
    message.name = object.name ?? "";
    message.shortenedName = object.shortenedName ?? 0;
    message.type = object.type ?? 0;
    message.numberOfLaps = object.numberOfLaps ?? 0;
    return message;
  },
};

type Builtin = Date | Function | Uint8Array | string | number | boolean | undefined;

export type DeepPartial<T> = T extends Builtin ? T
  : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

function isSet(value: any): boolean {
  return value !== null && value !== undefined;
}

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  fromJSON(object: any): T;
  toJSON(message: T): unknown;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
